import{_ as t,o as a,c as s,ah as l}from"./chunks/framework.DV4RPuBi.js";const h=JSON.parse('{"title":"Templates / Presets","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/templates-presets.md","filePath":"architecture/templates-presets.md","lastUpdated":1786017778000}'),r={name:"architecture/templates-presets.md"};function i(o,e,p,c,d,n){return a(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="templates-presets" tabindex="-1">Templates / Presets <a class="header-anchor" href="#templates-presets" aria-label="Permalink to &quot;Templates / Presets&quot;">​</a></h1><p>Templates 和 Presets 都是业务中立文件来源，但用于不同场景。</p><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p><code>templates/</code> 用于接入已有项目。它提供：</p><ul><li><code>AGENTS.md</code></li><li><code>.fe-harness/project.yaml</code></li><li>输入目录 README</li><li>PRODUCT / DESIGN / CURRENT_STATUS / DECISIONS</li><li>history 和 coverage 文件</li><li>API selection</li><li>Design Token 初始文件</li></ul><p><code>init</code> 使用 templates 时会先预检，不覆盖项目已维护文件。</p><h2 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to &quot;Presets&quot;">​</a></h2><p><code>presets/consumer-h5/</code> 用于创建新项目。它包含一个可运行的 minimal uni-app H5 项目：</p><ul><li><code>package.json</code></li><li><code>src/App.vue</code></li><li><code>src/pages.json</code></li><li><code>src/pages/index/index.vue</code></li><li><code>src/services/http.ts</code></li><li>Playwright 配置和测试</li><li>Harness 项目文档和输入目录</li></ul><h2 id="为什么不放业务示例页" tabindex="-1">为什么不放业务示例页 <a class="header-anchor" href="#为什么不放业务示例页" aria-label="Permalink to &quot;为什么不放业务示例页&quot;">​</a></h2><p>业务示例页会带来错误暗示。真实项目应该从 PRD/RP/UI/API 输入中生成业务页面，而不是从模板里继承一个虚假的默认业务。</p><p>所以 preset 只创建容器、目录和工程能力。输入为空时，项目保持“等待输入”。</p>',12)])])}const u=t(r,[["render",i]]);export{h as __pageData,u as default};
